// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

/**
 * @title DocumentRegistry
 * @notice Manages user-uploaded document metadata with verification workflow
 */
contract DocumentRegistry {
    struct Document {
        bytes32 contentHash;
        address uploader;
        uint256 timestamp;
        bool verified;
    }

    struct VerificationRequest {
        uint256 documentId;
        address verifier;
        uint256 deadline;
        bool completed;
    }

    mapping(uint256 => Document) public documents;
    mapping(uint256 => VerificationRequest) public verificationRequests;
    mapping(address => uint256[]) public userDocuments;
    mapping(address => bool) public authorizedVerifiers;

    uint256 public nextDocumentId;
    uint256 public nextRequestId;
    address public admin;

    // Delegation registry: delegator => delegate => scope
    mapping(address => mapping(address => bytes32)) public delegations;

    event DocumentUploaded(uint256 indexed docId, address indexed uploader);
    event VerificationRequested(uint256 indexed requestId, uint256 indexed docId);
    event DocumentVerified(uint256 indexed docId, address indexed verifier);
    event DelegationSet(address indexed delegator, address indexed delegate, bytes32 scope);

    modifier onlyAdmin() {
        require(msg.sender == admin, "Not admin");
        _;
    }

    constructor() {
        admin = msg.sender;
    }

    function addVerifier(address verifier) external onlyAdmin {
        authorizedVerifiers[verifier] = true;
    }

    function removeVerifier(address verifier) external onlyAdmin {
        authorizedVerifiers[verifier] = false;
    }

    function setDelegation(address delegate, bytes32 scope) external {
        delegations[msg.sender][delegate] = scope;
        emit DelegationSet(msg.sender, delegate, scope);
    }

    function uploadDocument(bytes32 contentHash) external returns (uint256) {
        require(contentHash != bytes32(0), "Empty hash");

        uint256 docId = nextDocumentId++;
        documents[docId] = Document({
            contentHash: contentHash,
            uploader: msg.sender,
            timestamp: block.timestamp,
            verified: false
        });
        userDocuments[msg.sender].push(docId);

        emit DocumentUploaded(docId, msg.sender);
        return docId;
    }

    function requestVerification(uint256 docId, address verifier, uint256 deadline) external returns (uint256) {
        Document storage doc = documents[docId];
        require(doc.uploader == msg.sender || _hasDelegation(doc.uploader, msg.sender, "VERIFY_REQUEST"), "Not authorized");
        require(doc.uploader != address(0), "Document not found");
        require(authorizedVerifiers[verifier], "Not a verifier");
        require(deadline > block.timestamp, "Invalid deadline");

        uint256 requestId = nextRequestId++;
        verificationRequests[requestId] = VerificationRequest({
            documentId: docId,
            verifier: verifier,
            deadline: deadline,
            completed: false
        });

        emit VerificationRequested(requestId, docId);
        return requestId;
    }

    /**
     * @notice Process a batch of verification completions
     * @param requestIds Array of request IDs to process
     * @param approvals Array of approval decisions
     */
    function batchVerify(uint256[] calldata requestIds, bool[] calldata approvals) external {
        require(requestIds.length == approvals.length, "Length mismatch");
        require(requestIds.length > 0, "Empty batch");

        for (uint256 i = 0; i < requestIds.length; i++) {
            _processVerification(requestIds[i], approvals[i]);
        }
    }

    function _processVerification(uint256 requestId, bool approved) internal {
        VerificationRequest storage request = verificationRequests[requestId];
        require(request.verifier != address(0), "Request not found");

        // Check verifier authorization through delegation chain
        address effectiveVerifier = _resolveVerifier(request.verifier, msg.sender);
        require(effectiveVerifier != address(0), "Not authorized verifier");
        require(!request.completed, "Already completed");
        require(block.timestamp <= request.deadline, "Deadline passed");

        request.completed = true;

        if (approved) {
            Document storage doc = documents[request.documentId];
            require(doc.uploader != address(0), "Document not found");
            doc.verified = true;
            emit DocumentVerified(request.documentId, effectiveVerifier);
        }
    }

    /**
     * @notice Resolves the effective verifier through delegation chain
     * @dev Returns address(0) if caller is not authorized
     */
    function _resolveVerifier(address assignedVerifier, address caller) internal view returns (address) {
        if (caller == assignedVerifier) {
            return caller;
        }

        // Check if assignedVerifier delegated to caller
        bytes32 delegation = delegations[assignedVerifier][caller];
        if (delegation == keccak256(abi.encodePacked("VERIFY_EXECUTE"))) {
            return assignedVerifier;
        }

        return address(0);
    }

    function _hasDelegation(address delegator, address delegate, string memory scope) internal view returns (bool) {
        return delegations[delegator][delegate] == keccak256(abi.encodePacked(scope));
    }

    /**
     * @notice Retrieve document with cross-reference validation
     * @param docId The document to retrieve
     * @param referenceDocId A reference document for cross-validation (0 for none)
     */
    function getDocumentWithReference(uint256 docId, uint256 referenceDocId) external view returns (
        bytes32 contentHash,
        address uploader,
        bool verified,
        bool crossValidated
    ) {
        Document storage doc = documents[docId];
        require(doc.uploader != address(0), "Document not found");

        contentHash = doc.contentHash;
        uploader = doc.uploader;
        verified = doc.verified;

        if (referenceDocId != 0) {
            Document storage refDoc = documents[referenceDocId];
            // Cross-validation: reference doc must exist and be verified
            crossValidated = refDoc.verified && refDoc.uploader != address(0);
        }
    }

    /**
     * @notice Transfer document ownership with optional batch processing
     * @param docId Document to transfer
     * @param newOwner New owner address
     * @param linkedDocIds Documents to link in the transfer context
     */
    function transferDocument(
        uint256 docId,
        address newOwner,
        uint256[] calldata linkedDocIds
    ) external {
        Document storage doc = documents[docId];
        require(doc.uploader == msg.sender, "Not owner");
        require(newOwner != address(0), "Invalid new owner");

        // Process linked documents - validate they share context
        for (uint256 i = 0; i < linkedDocIds.length; i++) {
            Document storage linkedDoc = documents[linkedDocIds[i]];
            // Linked docs must belong to same uploader for context sharing
            require(linkedDoc.uploader == msg.sender, "Linked doc not owned");
        }

        doc.uploader = newOwner;
        userDocuments[newOwner].push(docId);
    }

    /**
     * @notice Bulk upload with deferred verification scheduling
     * @param contentHashes Array of document hashes
     * @param verifier Optional verifier to auto-schedule (address(0) to skip)
     * @param verificationDeadline Deadline for auto-scheduled verifications
     */
    function bulkUploadWithVerification(
        bytes32[] calldata contentHashes,
        address verifier,
        uint256 verificationDeadline
    ) external returns (uint256[] memory docIds) {
        require(contentHashes.length > 0 && contentHashes.length <= 50, "Invalid batch size");
        require(verifier == address(0) || verificationDeadline > block.timestamp, "Invalid deadline");

        docIds = new uint256[](contentHashes.length);

        for (uint256 i = 0; i < contentHashes.length; i++) {
            require(contentHashes[i] != bytes32(0), "Empty hash in batch");

            uint256 docId = nextDocumentId++;
            documents[docId] = Document({
                contentHash: contentHashes[i],
                uploader: msg.sender,
                timestamp: block.timestamp,
                verified: false
            });
            userDocuments[msg.sender].push(docId);
            docIds[i] = docId;

            emit DocumentUploaded(docId, msg.sender);

            // Auto-schedule verification if verifier provided
            if (verifier != address(0) && authorizedVerifiers[verifier]) {
                uint256 requestId = nextRequestId++;
                verificationRequests[requestId] = VerificationRequest({
                    documentId: docId,
                    verifier: verifier,
                    deadline: verificationDeadline,
                    completed: false
                });
                emit VerificationRequested(requestId, docId);
            }
        }
    }
}
